import React from 'react';

const Projects = () => (
  <div>
    <h2>Projects</h2>
    <ul className="list-group">
      <li className="list-group-item">Plant Disease Recognition System using ML</li>
      <li className="list-group-item">Netflix Clone using MERN</li>
      <li className="list-group-item">Daily Order Publication System (HTML, CSS, JS, MongoDB)</li>
    </ul>
  </div>
);

export default Projects;
